func (q *Queries) SubmissionExists(ctx context.Context, arg SubmissionExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, submissionExists, arg.AssessmentID, arg.StudentID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const upsertGrade = `-- name: UpsertGrade :one
INSERT INTO grading_graderecord (submission_id, score, teacher_feedback, graded_at)
VALUES ($1, $2, $3, now())
ON CONFLICT (submission_id) DO UPDATE
  SET score = EXCLUDED.score, teacher_feedback = EXCLUDED.teacher_feedback, graded_at = now()
RETURNING id, submission_id, score, teacher_feedback, graded_at, (xmax = 0) AS created
`

type UpsertGradeParams struct {
	SubmissionID    int64
	Score           pgtype.Numeric
	TeacherFeedback pgtype.Text
}

type UpsertGradeRow struct {
	ID              int64
	SubmissionID    int64
	Score           pgtype.Numeric
	TeacherFeedback pgtype.Text
	GradedAt        pgtype.Timestamptz
	Created         bool
}

func (q *Queries) UpsertGrade(ctx context.Context, arg UpsertGradeParams) (UpsertGradeRow, error) {
	row := q.db.QueryRow(ctx, upsertGrade, arg.SubmissionID, arg.Score, arg.TeacherFeedback)
	var i UpsertGradeRow
	err := row.Scan(
		&i.ID,
		&i.SubmissionID,
		&i.Score,
		&i.TeacherFeedback,
		&i.GradedAt,
		&i.Created,
	)
	return i, err
}
